import numpy as np
import signal

def run_with_timeout(seconds=2):
    def handler(signum, frame):
        raise TimeoutError('base_repr timed out')
    old = signal.signal(signal.SIGALRM, handler)
    signal.setitimer(signal.ITIMER_REAL, seconds)
    try:
        out = np.base_repr(np.int8(-128))
        return {'returned': True, 'value': out}
    except TimeoutError:
        return {'returned': False, 'value': None}
    except Exception as e:
        return {'returned': False, 'value': f'EXC:{type(e).__name__}:{e}'}
    finally:
        signal.setitimer(signal.ITIMER_REAL, 0)
        signal.signal(signal.SIGALRM, old)

res = run_with_timeout(2)
# The probe framework records numeric/structured values via probe(name, value) if used;
# to be robust, just expose a couple of top-level variables.
returned = res['returned']
value = res['value']
probe('returned', float(returned))
# For string, store in a numeric-compatible way: length or sentinel.
# Framework primarily stores values; we include a hash-like numeric encoding.
if value is None:
    s = None
elif isinstance(value, str):
    s = value
else:
    s = str(value)
probe('value_len_or_none', -1 if s is None else len(s))
probe('value_is_expected', 1.0 if s == '-10000000' else 0.0)

